// Core tests: the 17 literal core cases from fixtures.json (expected
// values taken verbatim from the fixed spec candidate's file, never
// generated by the product), plus hand-derived boundary and validation
// cases. The SPEC's own rules are the oracle; every extra expected value
// below was computed by hand from those rules.

import assert from "node:assert/strict";
import test from "node:test";
import { formatReading, parseImportText, run } from "../public/js/core/tempo.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("interval 1999 and exactly 2000 do not reset; median of the pair is 1999.5", () => {
  assert.deepEqual(run({ taps: [0, 1999, 3999] }), {
    ok: true,
    result: {
      tapCount: 3,
      segmentStartIndex: 0,
      segmentTapCount: 3,
      segmentIntervalCount: 2,
      resetCount: 0,
      intervalCount: 2,
      windowIntervals: [1999, 2000],
      medianIntervalMs: 1999.5,
      meanIntervalMs: 1999.5,
      bpmMedian: 30.0,
      bpmMean: 30.0,
      beatsPerSecond: 0.5,
    },
  });
});

test("interval 2001 resets; the tap after the gap opens the new segment", () => {
  assert.deepEqual(run({ taps: [0, 2001, 2501] }), {
    ok: true,
    result: {
      tapCount: 3,
      segmentStartIndex: 1,
      segmentTapCount: 2,
      segmentIntervalCount: 1,
      resetCount: 1,
      intervalCount: 1,
      windowIntervals: [500],
      medianIntervalMs: 500,
      meanIntervalMs: 500,
      bpmMedian: 120.0,
      bpmMean: 120.0,
      beatsPerSecond: 2.0,
    },
  });
});

test("multiple resets: resetCount counts all, only the last segment is used", () => {
  assert.deepEqual(run({ taps: [0, 500, 4000, 4500, 9000, 9500] }), {
    ok: true,
    result: {
      tapCount: 6,
      segmentStartIndex: 4,
      segmentTapCount: 2,
      segmentIntervalCount: 1,
      resetCount: 2,
      intervalCount: 1,
      windowIntervals: [500],
      medianIntervalMs: 500,
      meanIntervalMs: 500,
      bpmMedian: 120.0,
      bpmMean: 120.0,
      beatsPerSecond: 2.0,
    },
  });
});

test("windowIntervals keep time order, not sorted order", () => {
  const outcome = run({ taps: [0, 900, 1000, 1500] });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result.windowIntervals, [900, 100, 500]);
  assert.equal(outcome.result.medianIntervalMs, 500);
  assert.equal(outcome.result.bpmMedian, 120.0);
});

test("a single interval spanning the whole range is a reset, leaving null estimates", () => {
  assert.deepEqual(run({ taps: [0, 10000000000000] }), {
    ok: true,
    result: {
      tapCount: 2,
      segmentStartIndex: 1,
      segmentTapCount: 1,
      segmentIntervalCount: 0,
      resetCount: 1,
      intervalCount: 0,
      windowIntervals: [],
      medianIntervalMs: null,
      meanIntervalMs: null,
      bpmMedian: null,
      bpmMean: null,
      beatsPerSecond: null,
    },
  });
});

test("the maximum timestamp alone is a valid single tap", () => {
  const outcome = run({ taps: [10000000000000] });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.tapCount, 1);
  assert.equal(outcome.result.bpmMedian, null);
});

test("exactly 512 taps are accepted; the window is the last 8 intervals", () => {
  const taps = Array.from({ length: 512 }, (_, i) => i * 1000);
  const outcome = run({ taps });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.tapCount, 512);
  assert.equal(outcome.result.segmentIntervalCount, 511);
  assert.equal(outcome.result.intervalCount, 8);
  assert.deepEqual(outcome.result.windowIntervals, [1000, 1000, 1000, 1000, 1000, 1000, 1000, 1000]);
  assert.equal(outcome.result.bpmMedian, 60.0);
  assert.equal(outcome.result.beatsPerSecond, 1.0);
});

test("RANGE is reported before NON_MONOTONIC for the same element", () => {
  assert.deepEqual(run({ taps: [0, -5] }), {
    ok: false,
    error: { code: "RANGE", field: "taps", row: 2 },
  });
});

test("schema failures: null, array, missing field, wrong type, extra field, accessor", () => {
  const schema = { ok: false, error: { code: "SCHEMA", field: null, row: null } };
  assert.deepEqual(run(null), schema);
  assert.deepEqual(run([0, 500]), schema);
  assert.deepEqual(run({}), schema);
  assert.deepEqual(run({ taps: "0,500" }), schema);
  assert.deepEqual(run({ taps: [0, 500], extra: 1 }), schema);
  const withGetter = {};
  Object.defineProperty(withGetter, "taps", {
    enumerable: true,
    get: () => [0, 500],
  });
  assert.deepEqual(run(withGetter), schema);
});

test("import text: empty and separators-only are EMPTY", () => {
  const empty = { ok: false, error: { code: "EMPTY", field: "taps", row: null } };
  assert.deepEqual(parseImportText(""), empty);
  assert.deepEqual(parseImportText("  , ,\n"), empty);
});

test("import text: commas and whitespace split tokens", () => {
  assert.deepEqual(parseImportText(" 0, 500  1000\n1500 "), {
    ok: true,
    taps: [0, 500, 1000, 1500],
  });
});

test("import text: leading zeros are INTEGER_FORMAT, overlong tokens INPUT_LIMIT", () => {
  assert.deepEqual(parseImportText("007"), {
    ok: false,
    error: { code: "INTEGER_FORMAT", field: "taps", row: 1 },
  });
  assert.deepEqual(parseImportText("0, 12345678901234567"), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "taps", row: 2 },
  });
});

test("import text: token above 10^13 is RANGE; 513 tokens are INPUT_LIMIT with row null", () => {
  assert.deepEqual(parseImportText("10000000000001"), {
    ok: false,
    error: { code: "RANGE", field: "taps", row: 1 },
  });
  const many = Array.from({ length: 513 }, (_, i) => String(i * 1000)).join(",");
  assert.deepEqual(parseImportText(many), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "taps", row: null },
  });
});

test("import text: a non-monotonic list still parses; the core reports it", () => {
  const parsed = parseImportText("0, 500, 499");
  assert.deepEqual(parsed, { ok: true, taps: [0, 500, 499] });
  assert.deepEqual(run({ taps: parsed.taps }), {
    ok: false,
    error: { code: "NON_MONOTONIC", field: "taps", row: 3 },
  });
});

test("formatReading assembles display strings from the rounded digits", () => {
  const steady = run({ taps: [0, 500, 1000, 1500, 2000] }).result;
  assert.deepEqual(formatReading(steady), {
    bpmMedianText: "120.0",
    bpmMeanText: "120.0",
    beatsPerSecondText: "2.00",
    medianIntervalText: "500",
    meanIntervalText: "500.0",
  });
  const half = run({ taps: [0, 500, 1001] }).result;
  assert.deepEqual(formatReading(half), {
    bpmMedianText: "119.9",
    bpmMeanText: "119.9",
    beatsPerSecondText: "2.00",
    medianIntervalText: "500.5",
    meanIntervalText: "500.5",
  });
  const two = run({ taps: [2000, 2600] }).result;
  assert.equal(formatReading(two).beatsPerSecondText, "1.67");
  assert.equal(formatReading(run({ taps: [1234] }).result), null);
});
